<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {ArrowLeft,ArrowUpRight,CheckCircle2,Copy,Download,FileArchive,History,LoaderCircle,Package,Plus,RefreshCw,Save,Search,Share2,ShieldCheck,Trash2,X} from 'lucide-vue-next';
import type {DatasetRelease,DatasetReleasePreview,ReleaseAsset,ReleaseList,ReleaseShare} from '../../../../packages/shared/src/releases';
import {ApiError,patch,post,remove,request} from '../api';
import {releaseFormSuggestions,acceptReleaseHint} from '../release-form-hints';
import {refreshedReleaseNotes,releaseCleanupWarning,shareableReleaseAssets} from '../release-ui';
import {releaseDialogKey} from '../release-dialog';
import {useAppStore} from '../stores/app';
import ReleaseMarkdown from './SafeMarkdown.vue';
import WorkflowSteps from './WorkflowSteps.vue';
const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{'open-version':[commitId:string]}>(),app=useAppStore(),route=useRoute(),router=useRouter();
const items=ref<DatasetRelease[]>([]),capabilities=ref<ReleaseList['capabilities']>({manage:false,share:false,export:false,hidden:false});
const loading=ref(false),busy=ref(false),error=ref(''),search=ref(''),filter=ref('all'),kind=ref<'releases'|'snapshots'>(route.query.releaseKind==='snapshots'?'snapshots':'releases');
const selectedId=ref(typeof route.query.release==='string'?route.query.release:''),selected=computed(()=>items.value.find(item=>item.id===selectedId.value));
const visible=computed(()=>items.value.filter(item=>(filter.value==='all'||filter.value==='published'&&item.status==='published'||filter.value==='drafts'&&['draft','queued','building','ready','failed'].includes(item.status))&&(item.version+' '+item.title).toLowerCase().includes(search.value.toLowerCase())));
const selectedPreview=computed(()=>selected.value?.datasetPreview);
const listGroups=computed(()=>kind.value==='snapshots'?[{key:'snapshots',title:'工作快照',items:visible.value}]:[{key:'published',title:'当前发布',items:visible.value.filter(item=>item.status==='published')},{key:'candidates',title:'待发布候选',items:visible.value.filter(item=>item.status!=='published')}]);
const creating=ref(false),editingId=ref(''),version=ref(''),title=ref(''),notes=ref(''),sourceRef=ref(props.branch),dialog=ref<HTMLElement>();
const formError=ref(''),formBaseline=ref(''),formPreview=ref<DatasetReleasePreview>(),formPreviewLoading=ref(false),formPreviewError=ref(''),lastGenerated=ref('');
const snapshotOpen=ref(false),snapshotAcknowledged=ref(false),snapshotError=ref(''),snapshotDialog=ref<HTMLElement>();
const errataOpen=ref(false),errataDraft=ref(''),shares=ref<ReleaseShare[]>([]),shareDays=ref('7'),shareAssetId=ref(''),shareLink=ref(''),showSharing=ref(false),showAudit=ref(false);
const shareAssets=computed(()=>shareableReleaseAssets(selected.value));
const suggestions=computed(()=>releaseFormSuggestions(items.value,decodeURIComponent(props.base.split('/').at(-1)??'dataset'),props.branch));
const formValue=()=>JSON.stringify([version.value,title.value,notes.value,sourceRef.value]);
const releaseFormDirty=computed(()=>creating.value&&formValue()!==formBaseline.value),formDirty=computed(()=>releaseFormDirty.value||!!errataDraft.value.trim()||snapshotOpen.value);
const notesCustomized=computed(()=>!!lastGenerated.value&&notes.value!==lastGenerated.value),previewSignature=computed(()=>JSON.stringify([sourceRef.value]));
const releaseStep=computed(()=>selected.value?.status==='published'||selected.value?.status==='withdrawn'?3:selected.value?.status==='ready'?2:['queued','building'].includes(selected.value?.status??'')?1:0);
const localLink=computed(()=>{try{return ['127.0.0.1','localhost','::1','[::1]'].includes(new URL(shareLink.value).hostname);}catch{return false;}});
const label=(status:string,itemKind:DatasetRelease['kind']='release')=>itemKind==='snapshot'&&status==='ready'?'可下载':({draft:'草稿',queued:'排队中',building:'打包中',ready:'待发布核对',published:'已发布',failed:'打包失败',withdrawn:'已撤回'}[status]??status);
const timestamp=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const bytes=(value:number)=>value<1024?value+' B':value<1024*1024?(value/1024).toFixed(1)+' KiB':(value/1024/1024).toFixed(1)+' MiB';
const assetName=(asset:ReleaseAsset)=>asset.kind==='manifest'?'版本清单':asset.audience==='internal'?'受权内部数据包':'数据集发布包';
let generation=0,previewGeneration=0,disposed=false,internalNavigation=0,poll:ReturnType<typeof setTimeout>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined;
let previousFocus:HTMLElement|null=null,snapshotPreviousFocus:HTMLElement|null=null;
function hint(field:'version'|'title'|'sourceRef',event?:KeyboardEvent){if(event&&(event.key!=='Tab'||event.shiftKey||event.altKey||event.ctrlKey||event.metaKey))return;const fields={version,title,sourceRef};fields[field].value=acceptReleaseHint(fields[field].value,suggestions.value[field]);}
async function load(quiet=false){const operation=++generation;if(!quiet)loading.value=true;error.value='';clearTimeout(poll);try{const value=await request<ReleaseList>(props.base+'/'+kind.value);if(operation!==generation||disposed)return;items.value=value.items;capabilities.value=value.capabilities;if(selectedId.value&&!items.value.some(item=>item.id===selectedId.value))selectedId.value='';if(items.value.some(item=>['queued','building'].includes(item.status)))poll=setTimeout(()=>void load(true),1500);}catch(cause){if(operation===generation)error.value=(cause as Error).message;}finally{if(operation===generation)loading.value=false;}}
async function discardErratum(){if(errataDraft.value.trim()&&!await app.confirmAction('当前勘误尚未保存，确认放弃并切换吗？',{title:'未保存的勘误',confirmLabel:'放弃并切换'}))return false;errataDraft.value='';errataOpen.value=false;return true;}
async function replaceSelection(release:string|undefined,releaseKind=kind.value){internalNavigation++;try{await router.replace({query:{...route.query,release,releaseKind}});}finally{internalNavigation--;}}
async function choose(item:DatasetRelease,afterWrite=false){if(busy.value&&!afterWrite||!await discardErratum())return;selectedId.value=item.id;showSharing.value=false;showAudit.value=false;shares.value=[];shareLink.value='';shareAssetId.value='';await replaceSelection(item.id);}
async function switchKind(value:'releases'|'snapshots'){if(busy.value||value===kind.value||!await discardErratum())return;kind.value=value;await replaceSelection(undefined,value);}
async function backList(){if(busy.value||!await discardErratum())return;selectedId.value='';await replaceSelection(undefined);}
async function loadFormPreview(){clearTimeout(previewTimer);const operation=++previewGeneration,context=props.base;if(!creating.value||!sourceRef.value.trim()){formPreviewLoading.value=false;return;}formPreviewError.value='';formPreviewLoading.value=true;try{const value=await post<DatasetReleasePreview>(context+'/releases/preview',{sourceRef:sourceRef.value.trim()});if(operation!==previewGeneration||context!==props.base||disposed||!creating.value)return;const wasClean=!releaseFormDirty.value;formPreview.value=value;notes.value=refreshedReleaseNotes(notes.value,lastGenerated.value,value.generatedNotes);lastGenerated.value=value.generatedNotes;if(wasClean)formBaseline.value=formValue();}catch(cause){if(operation===previewGeneration)formPreviewError.value=(cause as Error).message;}finally{if(operation===previewGeneration)formPreviewLoading.value=false;}}
async function openCreate(item?:DatasetRelease){if(busy.value||!await discardErratum())return;previousFocus=document.activeElement as HTMLElement;editingId.value=item?.id??'';version.value=editingId.value?item!.version:'';title.value=editingId.value?item!.title:'';notes.value=editingId.value?item!.notes:'';lastGenerated.value=editingId.value?item!.generatedNotes??'':'';sourceRef.value=editingId.value?item!.sourceRef:props.branch;formError.value='';formPreviewError.value='';formPreview.value=undefined;formBaseline.value=formValue();creating.value=true;await nextTick();dialog.value?.querySelector<HTMLInputElement>('input')?.focus();void loadFormPreview();}
async function closeCreate(){if(busy.value)return;if(releaseFormDirty.value&&!await app.confirmAction('当前发布表单尚未保存，确认关闭吗？',{title:'未保存的发布草稿',confirmLabel:'放弃表单'}))return;creating.value=false;clearTimeout(previewTimer);previewGeneration++;formPreviewLoading.value=false;previousFocus?.focus();}
async function regenerateNotes(){if(formPreviewLoading.value||!formPreview.value)return;if(notesCustomized.value&&!await app.confirmAction('用当前比较结果替换已编辑的说明？',{title:'重新采用自动说明',confirmLabel:'替换说明'}))return;notes.value=formPreview.value.generatedNotes;lastGenerated.value=formPreview.value.generatedNotes;}
async function save(){if(busy.value)return;formError.value='';const preview=formPreview.value;if(formPreviewLoading.value||!preview||formPreviewError.value||!preview.ok){formError.value=formPreviewError.value||'请先完成当前来源版本的发布检查。';return;}busy.value=true;try{const input={version:version.value.trim(),title:title.value.trim(),notes:notes.value,sourceRef:sourceRef.value.trim(),expectedCommit:preview.commitId,expectedBaselineReleaseId:preview.baselineReleaseId,expectedPlanDigest:preview.planDigest};let saved:DatasetRelease;if(editingId.value){const existing=items.value.find(item=>item.id===editingId.value);if(!existing)throw new Error('发布候选已变化，请刷新后核对。');saved=await patch(props.base+'/releases/'+existing.id,{...input,expectedRevision:existing.revision});}else saved=await post(props.base+'/releases',input);creating.value=false;kind.value='releases';await load(true);await choose(saved,true);app.notify('已保存完整数据集的固定发布候选，可继续校验打包。');}catch(cause){formError.value=(cause as Error).message;if(cause instanceof ApiError&&cause.code==='RELEASE_PREVIEW_CHANGED')void loadFormPreview();}finally{busy.value=false;}}
async function run(action:string,item:DatasetRelease){if(busy.value)return;if(action==='publish'&&!await app.confirmAction(`发布 ${item.version} 将替换现有已发布版本，并让旧下载链接和分享链接失效。每个项目只保留一个当前发布；分支和提交历史不受影响。新版本固定提交 ${item.commitId.slice(0,12)}，请核对内容和接收对象。`,{title:'发布此版本',confirmLabel:'正式发布'}))return;if(action==='withdraw'&&!await app.confirmAction(`撤回 ${item.version} 后，将移除当前发布及其文件，下载和分享链接失效；项目将暂无当前发布，分支及提交历史保留。`,{title:'撤回 Release',confirmLabel:'撤回版本'}))return;busy.value=true;error.value='';try{const result=await post<DatasetRelease|{removedReleaseId:string}>(props.base+'/'+(item.kind==='snapshot'?'snapshots':'releases')+'/'+item.id+'/'+action,{expectedRevision:item.revision});const cleanupWarning=action==='publish'&&'status'in result?releaseCleanupWarning(result):undefined;await load(true);app.notify(cleanupWarning??(action==='build'?'完整数据集打包任务已排队':action==='publish'?'新版已发布，旧下载链接已失效':action==='withdraw'?'版本已撤回':'操作已完成'));}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function openSnapshot(){if(!capabilities.value.export||!await discardErratum())return;snapshotAcknowledged.value=false;snapshotError.value='';snapshotOpen.value=true;}
async function newSnapshot(){if(busy.value||!snapshotAcknowledged.value)return;busy.value=true;snapshotError.value='';try{const saved=await post<DatasetRelease>(props.base+'/snapshots',{ref:props.branch});snapshotOpen.value=false;kind.value='snapshots';await load(true);await choose(saved,true);app.notify('完整工作快照打包已排队，未提交草稿不包含在内。');}catch(cause){snapshotError.value=(cause as Error).message;}finally{busy.value=false;}}
async function saveErratum(){if(!selected.value||!errataDraft.value.trim()||busy.value)return;busy.value=true;try{await post(props.base+'/releases/'+selected.value.id+'/errata',{expectedRevision:selected.value.revision,body:errataDraft.value});errataDraft.value='';errataOpen.value=false;await load(true);}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function loadShares(){if(!selected.value)return;showSharing.value=!showSharing.value;if(!showSharing.value)return;try{shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');}catch(cause){error.value=(cause as Error).message;}}
async function createShare(){if(!selected.value||busy.value||!shareAssets.value.some(asset=>asset.id===shareAssetId.value))return;busy.value=true;error.value='';shareLink.value='';try{const value=await post<ReleaseShare&{downloadPath:string}>(props.base+'/releases/'+selected.value.id+'/shares',{assetId:shareAssetId.value,expiresAt:new Date(Date.now()+Number(shareDays.value)*86400_000).toISOString()});shareLink.value=window.location.origin+value.downloadPath;shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');await load(true);}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function revoke(share:ReleaseShare){if(!selected.value||busy.value||!await app.confirmAction('撤销此下载链接？已下载副本不会收回。',{title:'撤销分享链接',confirmLabel:'撤销链接'}))return;busy.value=true;try{await remove(props.base+'/releases/'+selected.value.id+'/shares/'+share.id);shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');shareLink.value='';}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function copyLink(){try{await navigator.clipboard.writeText(shareLink.value);app.notify('分享链接已复制');}catch{app.notify('请选中文本手动复制。');}}
const allowLeave=async()=>internalNavigation>0||!busy.value&&(!formDirty.value||await app.confirmAction('当前发布表单、快照或勘误尚未完成，确认离开吗？',{title:'未保存的发布输入',confirmLabel:'放弃并离开'}));
const unregister=app.registerDraftGuard(allowLeave);onBeforeRouteLeave(allowLeave);onBeforeRouteUpdate((to,from)=>(['namespace','repo','tab'].some(key=>to.params[key]!==from.params[key])||to.query.release!==from.query.release||to.query.releaseKind!==from.query.releaseKind)?allowLeave():true);
function beforeUnload(event:BeforeUnloadEvent){if(formDirty.value||busy.value){event.preventDefault();event.returnValue='';}}
watch(previewSignature,()=>{formPreview.value=undefined;previewGeneration++;formPreviewLoading.value=false;clearTimeout(previewTimer);if(creating.value)previewTimer=setTimeout(()=>void loadFormPreview(),350);});
watch(snapshotOpen,async value=>{if(value){snapshotPreviousFocus=document.activeElement as HTMLElement;await nextTick();snapshotDialog.value?.querySelector<HTMLInputElement>('input')?.focus();}else snapshotPreviousFocus?.focus();});
watch(()=>[route.query.release,route.query.releaseKind],()=>{selectedId.value=typeof route.query.release==='string'?route.query.release:'';kind.value=route.query.releaseKind==='snapshots'?'snapshots':'releases';});
watch(()=>[props.base,kind.value],(value,previous)=>{if(previous&&value[0]!==previous[0]){creating.value=false;errataDraft.value='';previewGeneration++;formPreview.value=undefined;}selectedId.value=route.query.releaseKind===kind.value&&typeof route.query.release==='string'?route.query.release:'';showSharing.value=false;shareLink.value='';void load();});
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{disposed=true;generation++;previewGeneration++;clearTimeout(poll);clearTimeout(previewTimer);unregister();window.removeEventListener('beforeunload',beforeUnload);});
</script>

<template>
<section class="releases-page">
<header class="release-page-heading"><div><span class="release-eyebrow"><Package :size="15"/>完整数据集交付</span><h2>Releases</h2><p>每个项目只保留一个当前发布。新发布替换上一版，自动整理变更说明。</p></div><div><button v-if="capabilities.export" class="btn" :disabled="busy" @click="openSnapshot"><Download :size="15"/>导出工作快照</button><button v-if="capabilities.manage" class="btn btn-primary" :disabled="busy" @click="openCreate()"><Plus :size="16"/>创建 Release</button></div></header>
<p class="release-work-note"><ShieldCheck :size="16"/>发布整份已提交数据集，字段遵循“是否导出”设置。业务字段不再决定发布分组；未提交草稿不包含在内。</p>
<div class="release-view-tabs"><button :class="{active:kind==='releases'}" @click="switchKind('releases')">项目 Releases</button><button v-if="capabilities.export" :class="{active:kind==='snapshots'}" @click="switchKind('snapshots')">我的工作快照</button><button class="btn btn-ghost release-refresh" aria-label="刷新发布列表" :disabled="loading||busy" @click="load()"><RefreshCw :size="14"/></button></div><p v-if="error" class="error-state" role="alert">{{error}}</p><div v-if="loading&&!items.length" class="empty" role="status"><LoaderCircle class="spin" :size="24"/>正在读取固定版本…</div>
<template v-else-if="!selected"><div class="release-search"><label class="search-field"><Search :size="16"/><input v-model="search" aria-label="搜索发布版本" placeholder="搜索版本号或标题"/></label><select v-model="filter" aria-label="筛选发布状态"><option value="all">全部状态</option><option value="published">当前发布</option><option value="drafts">待发布候选</option></select></div><div v-if="!visible.length" class="panel release-empty"><Package :size="38"/><h3>{{items.length?'没有匹配的版本':kind==='snapshots'?'尚未创建工作快照':'尚未发布版本'}}</h3><p>选择已提交版本，检查变更说明后发布完整数据集。</p><button v-if="capabilities.manage&&kind==='releases'" class="btn btn-primary" :disabled="busy" @click="openCreate()">创建第一个 Release</button></div><template v-for="group in listGroups" :key="group.key"><h3 v-if="group.items.length" class="release-group-title">{{group.title}}</h3><button v-for="item in group.items" :key="item.id" class="release-list-item" @click="choose(item)"><span class="release-marker"><Package :size="20"/></span><div class="release-item-main"><div><strong>{{item.title}}</strong><span class="release-status" :class="item.status">{{label(item.status,item.kind)}}</span><span v-if="item.status==='published'" class="release-chip latest">当前发布</span></div><p><code>{{item.version}}</code><span>{{item.createdBy.name}} · {{timestamp(item.createdAt)}}</span></p><p class="release-list-notes">{{item.notes}}</p><footer><code>{{item.commitId.slice(0,12)}}</code><span>{{item.rowCount?.toLocaleString()??'—'}} 条样本</span><span>{{item.assets.length}} 项资产</span></footer></div><ArrowUpRight :size="17"/></button></template></template>
<article v-else class="release-detail"><button class="release-back" @click="backList"><ArrowLeft :size="15"/>返回版本列表</button><header class="release-detail-heading"><div><div class="release-detail-badges"><code>{{selected.version}}</code><span class="release-status" :class="selected.status">{{label(selected.status,selected.kind)}}</span><span v-if="selected.status==='published'" class="release-chip latest">当前发布</span></div><h2>{{selected.title}}</h2><p>{{selected.createdBy.name}} · {{timestamp(selected.createdAt)}}</p></div><div class="release-detail-actions"><button v-if="capabilities.manage&&selected.kind==='release'&&['draft','failed','ready'].includes(selected.status)" class="btn" :disabled="busy" @click="openCreate(selected)">编辑发布候选</button><button v-if="((selected.kind==='release'&&capabilities.manage)||(selected.kind==='snapshot'&&capabilities.export))&&['draft','failed','ready'].includes(selected.status)" class="btn btn-primary" :disabled="busy" @click="run('build',selected)"><Package :size="15"/>{{selected.status==='ready'?'重新校验打包':'校验并打包'}}</button><button v-if="capabilities.manage&&selected.kind==='release'&&selected.status==='ready'" class="btn btn-primary" :disabled="busy" @click="run('publish',selected)"><CheckCircle2 :size="15"/>核对并发布</button><button v-if="capabilities.manage&&selected.status==='published'" class="btn btn-ghost" :disabled="busy" @click="run('withdraw',selected)">撤回</button></div></header>
<WorkflowSteps v-if="selected.kind==='release'" :steps="['固定版本与说明','校验打包','核对发布','已发布版本']" :current="releaseStep" label="发布步骤"/>
<p v-if="releaseCleanupWarning(selected)" class="notice release-cleanup-warning" role="alert">{{releaseCleanupWarning(selected)}}</p><div class="release-content-grid"><div class="release-body"><p v-if="selected.kind==='snapshot'" class="notice">工作快照包含选定提交的完整数据集，不包含未提交草稿，不代表专家复核或评测验收结论。</p><div v-if="['queued','building'].includes(selected.status)" class="release-build-state" role="status"><LoaderCircle class="spin" :size="22"/><div><strong>{{label(selected.status,selected.kind)}}</strong><p>数据提交 {{selected.commitId.slice(0,12)}} 与比较基线已固定。</p></div></div><div v-if="selected.error" class="error-state" role="alert"><strong>{{selected.error}}</strong><ul v-if="selected.issues.length"><li v-for="issue in selected.issues" :key="issue">{{issue}}</li></ul></div>
<section v-if="selectedPreview" class="panel release-summary"><header><h3>数据与变更</h3><code>{{selectedPreview.commitId.slice(0,12)}}</code></header><div class="release-summary-stats"><span>样本<strong>{{selectedPreview.rowCount.toLocaleString()}}</strong></span><span>附件<strong>{{selectedPreview.attachmentCount.toLocaleString()}}</strong></span><span>导出字段<strong>{{selectedPreview.includedFields.length}}</strong></span></div><p>比较基线：{{selectedPreview.baselineVersion??'首个正式版本'}}<code v-if="selectedPreview.baselineCommitId"> · {{selectedPreview.baselineCommitId.slice(0,12)}}</code></p><div v-if="selectedPreview.comparison" class="release-summary-stats"><span>样本新增<strong>+{{selectedPreview.comparison.samples.added}}</strong></span><span>修改<strong>{{selectedPreview.comparison.samples.modified}}</strong></span><span>删除<strong>−{{selectedPreview.comparison.samples.removed}}</strong></span></div><div class="release-summary-stats"><span>文件新增<strong>+{{selectedPreview.changes.files.added}}</strong></span><span>修改<strong>{{selectedPreview.changes.files.modified}}</strong></span><span>删除<strong>−{{selectedPreview.changes.files.removed}}</strong></span></div><p v-for="warning in selectedPreview.warnings" :key="warning" class="notice">{{warning}}</p></section>
<section class="panel release-notes"><header><h3>版本说明</h3><span>受限 Markdown</span></header><ReleaseMarkdown :source="selected.notes"/><details v-if="selected.generatedNotes&&selected.generatedNotes!==selected.notes" class="release-generated-notes"><summary>查看生成时的变更记录</summary><ReleaseMarkdown :source="selected.generatedNotes"/></details><section v-if="selected.errata?.length" class="release-errata"><h4>发布后勘误</h4><article v-for="entry in selected.errata" :key="entry.id"><p>{{entry.actor.name}} · {{timestamp(entry.createdAt)}}</p><ReleaseMarkdown :source="entry.body"/></article></section><div v-if="capabilities.manage&&selected.kind==='release'&&['published','withdrawn'].includes(selected.status)" class="release-erratum-editor"><button class="btn btn-ghost" :disabled="busy" @click="errataOpen=!errataOpen">{{errataOpen?'收起':'添加发布后勘误'}}</button><form v-if="errataOpen" @submit.prevent="saveErratum"><label class="field">补充说明<textarea v-model="errataDraft" rows="4" maxlength="10000"/></label><button class="btn" :disabled="busy||!errataDraft.trim()">追加勘误并留痕</button></form></div></section>
<section class="panel release-assets"><header><h3><FileArchive :size="17"/>发布产物 <span>{{selected.assets.length}}</span></h3><span>固定 checksum</span></header><div v-if="!selected.assets.length" class="empty">{{selected.status==='failed'?'打包失败，没有可下载资产。':'打包完成后提供固定数据集与清单。'}}</div><div v-for="asset in selected.assets" :key="asset.id" class="release-asset"><FileArchive :size="18"/><div><a v-if="selected.status!=='withdrawn'" :href="'/api'+base+'/'+kind+'/'+selected.id+'/assets/'+asset.id" download>{{asset.name}}<Download :size="14"/></a><strong v-else>{{asset.name}}</strong><p class="release-asset-audience"><span>{{assetName(asset)}}</span></p><code>SHA-256 {{asset.sha256}}</code></div><span>{{bytes(asset.size)}}</span></div></section>
<section v-if="capabilities.share&&selected.kind==='release'&&selected.status==='published'" class="panel release-share"><header><h3><Share2 :size="16"/>固定资产分享</h3><button class="btn btn-ghost" @click="loadShares">{{showSharing?'收起':'管理下载链接'}}</button></header><div v-if="showSharing"><p>分享当前固定资产，不会授予项目或后续版本的访问权限。</p><div class="share-create"><label>分享资产<select v-model="shareAssetId" aria-label="选择可共享发布资产"><option value="">请选择资产</option><option v-for="asset in shareAssets" :key="asset.id" :value="asset.id">{{asset.name}} · {{assetName(asset)}}</option></select></label><label>有效期<select v-model="shareDays"><option value="1">1天</option><option value="7">7天</option><option value="30">30天</option></select></label><button class="btn" :disabled="busy||!shareAssetId||!shareAssets.some(asset=>asset.id===shareAssetId)" @click="createShare"><Plus :size="14"/>创建下载链接</button></div><p v-if="!shareAssets.length" class="release-help">此版本没有允许外链分享的资产。</p><div v-if="shareLink" class="created-share"><input :value="shareLink" readonly aria-label="刚创建的分享链接" @focus="($event.target as HTMLInputElement).select()"/><button class="btn" @click="copyLink"><Copy :size="14"/>复制</button><p v-if="localLink">当前地址只在本机可达；对外分发需要实际可达的受控部署地址。</p><p>链接令牌仅创建时显示一次，请勿写入公开文档或日志。</p></div><div v-for="share in shares" :key="share.id" class="share-row"><div><strong>{{share.revokedAt?'已撤销':Date.parse(share.expiresAt)<=Date.now()?'已过期':'有效'}}</strong><span>资产：{{selected.assets.find(asset=>asset.id===share.assetId)?.name??'固定资产'}}</span><span>{{share.createdBy.name}} · {{timestamp(share.expiresAt)}}</span></div><button v-if="!share.revokedAt&&Date.parse(share.expiresAt)>Date.now()" class="btn btn-ghost" :disabled="busy" @click="revoke(share)"><Trash2 :size="14"/>撤销</button></div></div></section>
</div><aside class="panel release-facts"><h3>版本信息</h3><dl><dt>固定提交</dt><dd><code>{{selected.commitId}}</code><button v-if="capabilities.hidden" class="btn btn-ghost" @click="emit('open-version',selected.commitId)">查看只读数据<ArrowUpRight :size="13"/></button></dd><dt>来源分支／版本</dt><dd>{{selected.sourceRef}}</dd><dt>比较基线</dt><dd>{{selectedPreview?.baselineVersion??'—'}}</dd><dt>样本数</dt><dd>{{selected.rowCount?.toLocaleString()??selectedPreview?.rowCount.toLocaleString()??'—'}}</dd><dt>创建</dt><dd>{{timestamp(selected.createdAt)}}</dd><dt>发布</dt><dd>{{timestamp(selected.publishedAt)}}</dd></dl><p>当前发布的资产与说明固定。再次发布会替换它并使旧链接失效；变更前基线信息保留在本版说明中。</p><button class="btn btn-ghost" @click="showAudit=!showAudit"><History :size="14"/>{{showAudit?'收起':'查看'}}操作记录</button><ol v-if="showAudit" class="release-audit"><li v-for="(entry,index) in selected.audit" :key="index"><strong>{{entry.action}}</strong><span>{{entry.actor.name}} · {{timestamp(entry.at)}}{{entry.detail?' · '+entry.detail:''}}</span></li></ol></aside></div></article>

<div v-if="creating" class="modal-backdrop release-dialog-backdrop" @click.self="closeCreate"><section ref="dialog" class="release-dialog" role="dialog" aria-modal="true" aria-labelledby="release-dialog-title" @keydown="releaseDialogKey" @keydown.esc.stop.prevent="closeCreate"><header><div><h2 id="release-dialog-title">{{editingId?'编辑发布候选':'创建 Release'}}</h2><p>发布完整数据集。系统比较上一正式版本生成说明，可继续补充。</p></div><button type="button" class="icon-button" :disabled="busy" aria-label="关闭发布表单" @click="closeCreate"><X :size="19"/></button></header><form @submit.prevent="save"><fieldset :disabled="busy"><div class="release-form-grid"><label class="field">版本号<input v-model="version" required maxlength="80" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}" :placeholder="suggestions.version" @keydown="hint('version',$event)"/><small>空值按 Tab 采用建议。</small></label><label class="field">来源分支／提交<input v-model="sourceRef" required maxlength="160" :placeholder="suggestions.sourceRef" @keydown="hint('sourceRef',$event)"/></label></div><label class="field">版本标题<input v-model="title" required maxlength="240" :placeholder="suggestions.title" @keydown="hint('title',$event)"/></label>
<section class="release-form-summary" aria-label="发布检查与自动说明"><header><h3>数据与变更检查</h3><button class="btn btn-ghost" type="button" :disabled="formPreviewLoading||busy||!sourceRef.trim()" @click="loadFormPreview"><RefreshCw :size="14"/>重新检查</button></header><p v-if="formPreviewLoading" class="release-help" role="status"><LoaderCircle class="spin" :size="14"/>正在固定数据提交并比较上一正式版本…</p><p v-if="formPreviewError" class="error-state" role="alert">{{formPreviewError}}</p><template v-if="formPreview"><div class="release-summary-stats"><span>样本<strong>{{formPreview.rowCount.toLocaleString()}}</strong></span><span>附件<strong>{{formPreview.attachmentCount.toLocaleString()}}</strong></span><span>导出字段<strong>{{formPreview.includedFields.length}}</strong></span></div><p>比较基线：<strong>{{formPreview.baselineVersion??'首个正式版本'}}</strong><code v-if="formPreview.baselineCommitId"> · {{formPreview.baselineCommitId.slice(0,12)}}</code></p><div v-if="formPreview.comparison" class="release-summary-stats"><span>样本新增<strong>+{{formPreview.comparison.samples.added}}</strong></span><span>修改<strong>{{formPreview.comparison.samples.modified}}</strong></span><span>删除<strong>−{{formPreview.comparison.samples.removed}}</strong></span></div><div class="release-summary-stats"><span>文件新增<strong>+{{formPreview.changes.files.added}}</strong></span><span>修改<strong>{{formPreview.changes.files.modified}}</strong></span><span>删除<strong>−{{formPreview.changes.files.removed}}</strong></span></div><p v-if="formPreview.excludedFields.length">未导出字段：{{formPreview.excludedFields.join('、')}}</p><p v-for="warning in formPreview.warnings" :key="warning" class="notice">{{warning}}</p><ul v-if="formPreview.issues.length" class="error-state"><li v-for="issue in formPreview.issues" :key="issue">{{issue}}</li></ul></template></section>
<div class="release-notes-label"><label for="release-notes">版本说明</label><button class="btn btn-ghost" type="button" :disabled="busy||formPreviewLoading||!formPreview" @click="regenerateNotes"><RefreshCw :size="13"/>重新采用自动说明</button></div><textarea id="release-notes" v-model="notes" class="release-notes-input" rows="12" maxlength="30000" placeholder="数据检查完成后自动生成变更说明，可直接编辑。"/><p class="release-help">{{notesCustomized?'已保留你编辑的说明。重新检查不会覆盖它，可显式重新采用自动说明。':'根据固定数据与比较基线生成，不发送样本正文到外部服务。'}}</p></fieldset><p v-if="formError" class="error-state" role="alert">{{formError}}</p><footer><button class="btn" type="button" :disabled="busy" @click="closeCreate">取消</button><button class="btn btn-primary" :disabled="busy||formPreviewLoading||!!formPreviewError||!formPreview?.ok||!version.trim()||!title.trim()"><LoaderCircle v-if="busy" class="spin" :size="15"/><Save v-else :size="15"/>保存发布候选</button></footer></form></section></div>

<div v-if="snapshotOpen" class="modal-backdrop release-dialog-backdrop" @click.self="!busy&&(snapshotOpen=false)"><form ref="snapshotDialog" class="release-snapshot-dialog" role="dialog" aria-modal="true" aria-labelledby="snapshot-title" @keydown="releaseDialogKey" @keydown.esc.stop.prevent="!busy&&(snapshotOpen=false)" @submit.prevent="newSnapshot"><header><h2 id="snapshot-title">导出完整工作快照</h2><button type="button" class="icon-button" :disabled="busy" aria-label="关闭快照表单" @click="snapshotOpen=false"><X :size="18"/></button></header><p>固定分支 <code>{{branch}}</code> 已提交的完整数据集，按字段导出配置打包。不包含未提交草稿，不代表正式发布或专家复核结论。</p><label class="release-snapshot-check"><input v-model="snapshotAcknowledged" type="checkbox"/>我已核对整份数据集的内容、导出字段与接收对象。</label><p v-if="snapshotError" class="error-state" role="alert">{{snapshotError}}</p><footer><button type="button" class="btn" :disabled="busy" @click="snapshotOpen=false">取消</button><button class="btn btn-primary" :disabled="busy||!snapshotAcknowledged"><Download :size="14"/>生成工作快照</button></footer></form></div>
</section>
</template>
<style src="./releases.css"></style>
